// Modo: Run Once for Each Item.
// Aparca el evento a la espera de que pulses un boton. Solo hay un usuario,
// asi que con guardar UNA pendiente a la vez sobra: si dictas dos eventos
// seguidos, el segundo tapa al primero y el boton viejo queda caducado.

const estado = $getWorkflowStaticData('global');
const nota = $json;

// El message_id de tu nota identifica la pendiente y cabe de sobra en los
// 64 bytes que Telegram deja meter en callback_data.
const token = String(nota.message_id);

estado.pendiente = {
  // Solo hay un pendiente a la vez y ahora puede ser de dos clases, asi que
  // hay que decir cual: la resolucion del boton se bifurca por aqui.
  tipo: 'guardar',
  token,
  nombreFichero: nota.nombreFichero,
  contenido: nota.contenido,
  resumen: nota.resumen,
  // Lo que hara falta para indexar en Qdrant cuando confirmes. Se guarda aqui
  // porque la ejecucion que atiende el boton es otra: alli no ha corrido
  // "Componer nota" y nada de lo que calculo existe ya.
  indice: {
    titulo: nota.titulo,
    tipo: nota.tipo,
    cuando: nota.cuando ?? '',
    tags: (nota.tags ?? []).join(', '),
    creado: nota.creado,
    texto: nota.textoIndexable,
  },
  creado: Date.now(),
};

return { json: { ...nota, token } };

function leerVault() {
  // El texto lo resuelve el nodo "Extraer el texto", pero ese nodo se queda
  // SOLO con la clave que le pides y tira el resto del json, el nombre del
  // fichero incluido. Hay que ir a buscarlo al nodo de lectura, que saca los
  // items en el mismo orden, y emparejarlos por posicion.
  const leidos = $('Leer el vault').all();
  const ficheros = [];
  $input.all().forEach((item, i) => {
    const j = item.json ?? {};
    if (typeof j.contenido !== 'string' || !j.contenido) return;
    const src = leidos[i] ?? {};
    const nombre = src.json?.fileName ?? src.binary?.data?.fileName;
    if (!nombre) return;
    ficheros.push({ nombre, texto: j.contenido });
  });
  return ficheros;
}

function frontmatter(texto) {
  const m = texto.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!m) return {};
  const campos = {};
  for (const linea of m[1].split(/\r?\n/)) {
    const i = linea.indexOf(':');
    if (i === -1) continue;
    const clave = linea.slice(0, i).trim();
    let valor = linea.slice(i + 1).trim();
    if (valor.startsWith('"') && valor.endsWith('"')) {
      valor = valor.slice(1, -1).replace(/\\"/g, '"');
    }
    campos[clave] = valor;
  }
  return campos;
}

// Modo: Run Once for All Items.
// Te han pedido cancelar o borrar algo. Busca en el vault que puede ser, deja
// los candidatos aparcados en staticData y monta la pregunta con botones.
//
// La busqueda es por palabras, no por significado, y es a proposito. En un
// borrado interesa acertar poco antes que equivocarse: que no encuentre "lo
// del medico" cuando la nota dice "dentista" se arregla repitiendolo con otras
// palabras, pero borrar la nota que no era no se arregla. Ademas asi se lee el
// vault directamente y no dependemos de que el indice este al dia.

const MAX_CANDIDATOS = 3;

const DIAS = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];
const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio',
               'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];

const peticion = $('Componer nota').first().json;
const busqueda = String(peticion.busqueda ?? '').trim();
const ahora = DateTime.fromISO(peticion.ahora, { zone: 'Europe/Madrid' });

// Sin acentos, sin signos y en minusculas, para que "revisión" y "revision"
// sean la misma palabra.
const normalizar = (s) => String(s ?? '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

// Palabras que salen en cualquier frase y no distinguen una nota de otra.
const VACIAS = new Set(['el', 'la', 'los', 'las', 'un', 'una', 'unos', 'unas',
  'de', 'del', 'al', 'en', 'que', 'lo', 'mi', 'me', 'se', 'con', 'para', 'por',
  'es', 'este', 'esta', 'esto', 'eso', 'esa', 'cita', 'nota', 'cosa', 'tengo',
  'tenia', 'hay', 'todo', 'cancela', 'cancelar', 'borra', 'borrar', 'olvida',
  'olvidar', 'quita', 'quitar', 'anula', 'anular']);

const claves = normalizar(busqueda).split(' ')
  .filter((p) => p.length > 2 && !VACIAS.has(p));

const candidatos = [];

for (const f of leerVault()) {
  const fm = frontmatter(f.texto);
  if (String(fm.cancelado).trim() === 'true') continue;   // ya estaba cancelada

  const heno = normalizar((fm.titulo ?? '') + ' ' + (fm.tags ?? '') + ' ' + f.texto);
  const palabras = new Set(heno.split(' '));

  let puntos = 0;
  for (const c of claves) {
    if (palabras.has(c)) puntos += 2;          // la palabra entera
    else if (heno.includes(c)) puntos += 1;    // dentro de otra palabra
  }
  if (!puntos) continue;

  const d = fm.cuando ? DateTime.fromISO(fm.cuando, { zone: 'Europe/Madrid' }) : null;
  const valida = d && d.isValid;

  candidatos.push({
    fichero: f.nombre,
    texto: f.texto,
    titulo: fm.titulo || f.nombre.replace(/\.md$/, ''),
    tipo: fm.tipo || 'nota',
    cuando: valida ? d.toFormat("yyyy-LL-dd'T'HH:mm:ss") : null,
    // A igualdad de palabras gana lo que cae mas cerca en el tiempo: cancelas
    // la cita que viene, no una parecida del ano pasado.
    dias: valida ? Math.abs(d.diff(ahora, 'days').days) : 9999,
    puntos,
    humana: valida
      ? DIAS[d.weekday - 1] + ' ' + d.day + ' de ' + MESES[d.month - 1] + ', ' + d.toFormat('HH:mm')
      : null,
  });
}

candidatos.sort((a, b) => (b.puntos - a.puntos) || (a.dias - b.dias));
const elegidos = candidatos.slice(0, MAX_CANDIDATOS);

const base = {
  chat_id: peticion.chat_id,
  message_id: peticion.message_id,
};

if (!elegidos.length) {
  // Ojo: no se toca estado.pendiente. Si tenias un evento esperando
  // confirmacion, una busqueda fallida no deberia cargarselo.
  const dicho = claves.length ? ' que se parezca a "' + claves.join(' ') + '"' : '';
  return [{ json: { ...base, teclado: null, hayCandidatos: false,
    texto: 'No encuentro nada' + dicho + '. Dímelo con las palabras que usaste al apuntarlo.' } }];
}

const estado = $getWorkflowStaticData('global');
const token = String(peticion.message_id);

estado.pendiente = {
  tipo: 'borrar',
  token,
  creado: Date.now(),
  candidatos: elegidos.map((e) => ({
    fichero: e.fichero,
    texto: e.texto,
    titulo: e.titulo,
    humana: e.humana,
  })),
};

const lineas = ['¿Cuál cancelo?', ''];
elegidos.forEach((e, i) => {
  lineas.push((i + 1) + '. ' + e.titulo);
  if (e.humana) lineas.push('   ' + e.humana);
});

const botones = elegidos.map((e, i) => ({
  text: String(i + 1),
  callback_data: 'del:' + token + ':' + i,
}));
botones.push({ text: '❌ Ninguna', callback_data: 'no:' + token });

return [{
  json: {
    ...base,
    hayCandidatos: true,
    texto: lineas.join('\n'),
    teclado: { inline_keyboard: [botones] },
  },
}];

